import {createStringAudio} from './string-audio.js';
import {createStringControls,stringControlsMarkup} from './string-controls.js';
import {createStringSession,fitStringCamera} from './string-session.js';
import * as THREE from 'three';import {MUSIC_TRACKS} from '../audio/game-audio.js';import {createPianoAudio} from '../audio/piano-audio.js';import {createMusicSession,fitMusicCamera} from './music-session.js';
const NAMES=['도','도♯','레','레♯','미','파','파♯','솔','솔♯','라','라♯','시'];
export const PIANO_CODES=['KeyZ','KeyS','KeyX','KeyD','KeyC','KeyV','KeyG','KeyB','KeyH','KeyN','KeyJ','KeyM','KeyQ','Digit2','KeyW','Digit3','KeyE','KeyR','Digit5','KeyT','Digit6','KeyY','Digit7','KeyU','KeyI'];
export function pianoKeyLayout(base=60){let whites=0;return Array.from({length:25},(_,i)=>{const midi=base+i,black=[1,3,6,8,10].includes(midi%12),left=black?whites*52-20:whites++*52;return{midi,black,left,label:NAMES[midi%12]+(Math.floor(midi/12)-1),shortcut:PIANO_CODES[i].replace('Key','').replace('Digit','')};});}
const PIANO_BODY=`<div class="piano-top"><label>음역 <select id="piano-range">${[[21,'아주 낮게 · A0–A2'],[36,'낮게 · C2–C4'],[48,'가운데 아래 · C3–C5'],[60,'가운데 · C4–C6'],[72,'높게 · C5–C7'],[84,'아주 높게 · C6–C8']].map(([n,t])=>`<option value="${n}"${n===60?' selected':''}>${t}</option>`).join('')}</select></label><button id="piano-mute" aria-pressed="false">소리 끄기</button><button id="piano-pause" aria-pressed="false">잠깐 쉬기</button></div><div class="keyboard-scroll" id="keyboard-scroll" tabindex="0" aria-label="두 옥타브 건반. 옆으로 스크롤할 수 있어요"><div class="piano-keyboard" id="piano-keyboard"></div></div><div class="piano-foot"><button id="piano-scroll-low" aria-label="낮은 쪽 건반 보기">낮은 쪽</button><p id="piano-status" role="status">건반을 누르고 떼어 보세요</p><button id="piano-scroll-high" aria-label="높은 쪽 건반 보기">높은 쪽</button></div><p class="music-caption">88건반 중 두 옥타브씩 보여요 · Z~M / Q~I로 연주 · 합성 피아노풍 음색</p>`;
const LISTEN_BODY=`<div class="listening-tracks" role="group" aria-label="직접 작곡한 음악 다섯 곡">${MUSIC_TRACKS.map(t=>`<button data-track="${t.id}" aria-pressed="false"><strong>${t.title}</strong><span>${t.genre} · ${Math.round(t.seconds)}초</span></button>`).join('')}</div><div class="listening-controls"><button class="primary" id="listen-play">재생</button><button id="listen-mute" aria-pressed="false">음소거</button><label>음량 <input id="listen-volume" type="range" min="0" max="100" value="70" aria-label="감상 음악 음량"></label></div><p id="listen-status" role="status">곡을 고른 뒤 재생해요</p><p class="music-caption">이 게임을 위해 새로 만든 곡을 합성 악기로 연주해요 · 피아노·재즈·앰비언트·포크·8비트</p>`;
/** Temporary seated sessions are mounted only after the dialog has acquired its normal lock. */
export function createMusicController({ui,getView,getActors,audio,stage,reduced=false,isAllowed=()=>true,document:doc=globalThis.document,window:win=globalThis.window,sessionFactory=createMusicSession,fitCamera=fitMusicCamera}){
 const camera=new THREE.OrthographicCamera(-5,5,4,-4,.1,100);let live=null;const $=id=>doc.querySelector('#'+id);
 function listen(node,type,fn){node?.addEventListener(type,fn);live.listeners.push([node,type,fn]);}
 function clean(resume=true,s=live){if(!s||live!==s)return;live=null;s.controls?.dispose();s.engine?.dispose();for(const id of s.timers)clearTimeout(id);try{s.session.dispose();}finally{s.releaseSeat?.();}s.view.schoolView?.piano?.resetKeys();audio.stopListening();for(const[node,type,fn]of s.listeners)node?.removeEventListener(type,fn);for(const id of s.pointers.keys())try{$('piano-keyboard')?.releasePointerCapture(id);}catch{}s.observer?.disconnect();stage.classList.remove('music-open');doc.body?.classList.remove('music-open');if(resume)s.onClose?.();}
 function close(resume=true){if(!live)return;clean(resume);ui.close();}
 function clearKeys(){if(!live)return;live.engine?.allNotesOff();for(const id of live.pointers.keys())try{$('piano-keyboard')?.releasePointerCapture(id);}catch{}live.pointers.clear();live.keys.clear();}
 function pause(){if(!live)return;if(live.kind==='cello'||live.kind==='harp'){live.controls?.pause();return;}if(live.kind==='piano'){clearKeys();live.paused=true;$('piano-pause').textContent='계속 연주';$('piano-pause').setAttribute('aria-pressed','true');$('piano-status').textContent='잠깐 쉬는 중이에요. 계속 연주를 누르면 이어져요';}else{live.playRequest++;audio.pauseListening();live.playing=false;$('listen-play').textContent='재생';$('listen-status').textContent='잠깐 멈췄어요';}}
 function renderKeys(){const keys=pianoKeyLayout(live.base),el=$('piano-keyboard'),whites=keys.filter(k=>!k.black).length;el.style.width=`${whites*52}px`;el.innerHTML=keys.map(k=>`<button class="piano-key ${k.black?'black-key':'white-key'}" data-midi="${k.midi}" style="left:${k.left}px" aria-label="${k.label}, 키보드 ${k.shortcut}" aria-pressed="false"><strong>${k.label}</strong><span>${k.shortcut}</span></button>`).join('');}
 function press(midi,source){if(!live||live.paused)return;live.engine.noteOn(midi,source);$('piano-status').textContent=`${NAMES[midi%12]}${Math.floor(midi/12)-1}${live.engine.muted?' · 음소거 중':''}`;}
 function mountPiano(){const s=live;
  // The entry is already a user gesture. Prepare the shared output before a brief
  // first key press, while noteOn/noteOff still cancel every released async voice.
  void audio.unlock();
  s.engine=createPianoAudio({getAudio:()=>audio.unlock(),onPressed(midi,on){if(live!==s)return;on?s.pressed.add(midi):s.pressed.delete(midi);s.view.schoolView.piano.setPressed(midi,on);const b=$('piano-keyboard')?.querySelector(`[data-midi="${midi}"]`);b?.setAttribute('aria-pressed',String(on));s.session.setPressed(s.pressed);},onError:text=>{if(live===s)$('piano-status').textContent=text;}});renderKeys();const el=$('piano-keyboard');
  listen(el,'pointerdown',e=>{const b=e.target.closest?.('[data-midi]');if(!b||e.button>0||s.paused)return;e.preventDefault();const midi=Number(b.dataset.midi);s.pointers.set(e.pointerId,midi);try{el.setPointerCapture(e.pointerId);}catch{}press(midi,'pointer:'+e.pointerId);});
  const release=e=>{const midi=s.pointers.get(e.pointerId);if(midi===undefined)return;s.engine.noteOff(midi,'pointer:'+e.pointerId);s.pointers.delete(e.pointerId);try{el.releasePointerCapture(e.pointerId);}catch{}};for(const t of['pointerup','pointercancel','lostpointercapture'])listen(el,t,release);
  listen(el,'click',e=>{if(e.detail!==0||Date.now()<s.suppressClickUntil)return;const b=e.target.closest?.('[data-midi]');if(!b||s.paused||s.keys.has('Space')||s.keys.has('Enter'))return;const midi=Number(b.dataset.midi);press(midi,'assistive');s.timers.add(setTimeout(()=>s.engine.noteOff(midi,'assistive'),180));});
  listen(win,'keydown',e=>{if(live!==s||e.ctrlKey||e.metaKey||e.altKey||e.isComposing||e.repeat||s.paused||/^(INPUT|SELECT|TEXTAREA)$/.test(e.target?.tagName))return;let midi;const b=e.target.closest?.('[data-midi]');if(b&&['Space','Enter'].includes(e.code)){midi=Number(b.dataset.midi);s.suppressClickUntil=Date.now()+500;}else{const i=PIANO_CODES.indexOf(e.code);if(i<0)return;midi=s.base+i;}e.preventDefault();if(s.keys.has(e.code))return;s.keys.set(e.code,midi);press(midi,'key:'+e.code);});listen(win,'keyup',e=>{const midi=s.keys.get(e.code);if(midi!==undefined){e.preventDefault();s.engine.noteOff(midi,'key:'+e.code);s.keys.delete(e.code);}});
  listen($('piano-range'),'change',()=>{clearKeys();s.base=Number($('piano-range').value);renderKeys();$('keyboard-scroll').scrollLeft=0;});listen($('piano-mute'),'click',()=>{clearKeys();s.engine.setMuted(!s.engine.muted);$('piano-mute').setAttribute('aria-pressed',String(s.engine.muted));$('piano-mute').textContent=s.engine.muted?'소리 켜기':'소리 끄기';});listen($('piano-pause'),'click',()=>{if(!s.paused){pause();return;}s.paused=false;$('piano-pause').textContent='잠깐 쉬기';$('piano-pause').setAttribute('aria-pressed','false');$('piano-status').textContent='다시 연주해요';});for(const[id,sign]of[['piano-scroll-low',-1],['piano-scroll-high',1]])listen($(id),'click',()=>{$('keyboard-scroll').scrollLeft+=sign*312;});
 }
 function mountListen(){const s=live;s.track=MUSIC_TRACKS[0].id;let muted=false,volume=.7;const show=()=>{for(const b of doc.querySelectorAll('[data-track]'))b.setAttribute('aria-pressed',String(b.dataset.track===s.track));};const play=async()=>{const token=++s.playRequest;s.playing=true;$('listen-play').textContent='일시정지';$('listen-status').textContent='음악을 준비하는 중…';const ok=await audio.listen(s.track);if(live!==s||token!==s.playRequest)return;s.playing=ok;$('listen-play').textContent=ok?'일시정지':'재생';$('listen-status').textContent=ok?MUSIC_TRACKS.find(t=>t.id===s.track).title+' · 듣는 중':audio.snapshot().error||'재생을 다시 눌러 주세요';};for(const b of doc.querySelectorAll('[data-track]'))listen(b,'click',()=>{const was=s.playing;s.playRequest++;s.track=b.dataset.track;show();if(was)play();else $('listen-status').textContent='재생을 누르면 들을 수 있어요';});listen($('listen-play'),'click',()=>{if(s.playing)pause();else play();});listen($('listen-mute'),'click',()=>{muted=!muted;audio.setListeningVolume(muted?0:volume);$('listen-mute').setAttribute('aria-pressed',String(muted));$('listen-mute').textContent=muted?'소리 켜기':'음소거';});listen($('listen-volume'),'input',()=>{volume=Number($('listen-volume').value)/100;audio.setListeningVolume(muted?0:volume);});audio.setListeningVolume(.7);show();}
 function mountStrings(){const s=live;s.engine=createStringAudio({kind:s.kind,getAudio:()=>audio.unlock(),isActive:()=>live===s&&stage.classList.contains('music-open')&&!!$('music-string-controls')&&$('music-string-controls').isConnected!==false,onError:text=>{const n=$('music-string-controls')?.querySelector('[data-string-status]');if(live===s&&n)n.textContent=text;}});s.controls=createStringControls({container:$('music-string-controls'),kind:s.kind,engine:s.engine,document:doc,window:win,isActive:()=>live===s,onNote:midi=>s.session.setNote(midi),onBow:value=>s.session.setBow(value),onPluck:midi=>s.session.pluck(midi),onClose:close});}
 function open(kind='piano',{onClose=null}={}){
  if(live||!isAllowed()||!['piano','listen','cello','harp'].includes(kind))return false;
  const view=getView();if(kind==='piano'&&!view?.schoolView?.piano)return false;
  const strings=kind==='cello'||kind==='harp';if(strings&&!view?.root?.getObjectByName('music.'+kind))return false;
  // Claim the shared chair before ui.workshop takes its modal lock and cancels NPC intent.
  const lease=kind==='listen'?view?.acquireResidentListeningSeat?.():null;
  if(kind==='listen'&&view?.acquireResidentListeningSeat&&!lease)return false;
  let released=false;const releaseSeat=()=>{if(released)return;released=true;lease?.release();};
  const abandon=()=>{releaseSeat();if(kind==='listen')view?.cancelResidentEquipmentRequest?.();};
  try{
   const opened=ui.workshop(kind==='piano'?'그랜드 피아노':kind==='cello'?'첼로 켜기':kind==='harp'?'하프 튕기기':'헤드셋 음악 감상',`<div class="music-layout"><div class="music-stage" id="music-stage" role="img" aria-label="${kind==='piano'?'도름이가 그랜드 피아노에 앉아 연주하는 모습':strings?'도름이가 실제 악기를 연주하는 모습':'도름이가 헤드셋을 쓰고 음악을 듣는 모습'}"></div><section class="music-panel">${kind==='piano'?PIANO_BODY:strings?'<div id="music-string-controls">'+stringControlsMarkup(kind)+'</div>':LISTEN_BODY}</section></div>`,()=>{
    let session;try{session=(strings?createStringSession:sessionFactory)({zoneRoot:view.root,...getActors(),kind,reduced});}catch{abandon();ui.close();ui.toast('자리를 준비하지 못했어요. 다시 열어 주세요');return;}
    const s=live={kind,view,session,onClose,releaseSeat,listeners:[],pointers:new Map(),keys:new Map(),pressed:new Set(),timers:new Set(),suppressClickUntil:0,paused:false,base:60,fit:null,playing:false,playRequest:0};
    try{
     stage.classList.add('music-open');doc.body?.classList.add('music-open');
     if(kind==='piano')mountPiano();else if(strings)mountStrings();else mountListen();
     listen(win,'blur',()=>{if(live===s)pause();});listen(doc,'visibilitychange',()=>{if(live===s&&doc.hidden)pause();});
     const resize=()=>{if(live===s)viewport(stage.clientWidth||320,stage.clientHeight||568);};
     listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);
     if(typeof globalThis.ResizeObserver==='function'){s.observer=new globalThis.ResizeObserver(resize);s.observer.observe($('music-stage'));}resize();
    }catch{clean(false,s);abandon();ui.close();ui.toast('연주를 준비하지 못했어요. 다시 열어 주세요');return;}
    return()=>clean(true,s);
   },{kind:'music-workshop',closeLabel:'나가기'});
   if(!opened)abandon();return opened;
  }catch{
   if(live?.releaseSeat===releaseSeat)clean(false,live);abandon();ui.close();ui.toast('자리를 준비하지 못했어요. 다시 열어 주세요');return false;
  }
 }
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const box=$('music-stage').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,box.left-base.left),y=Math.max(0,box.top-base.top),r={x,y,width:Math.max(1,Math.min(box.width,width-x)),height:Math.max(1,Math.min(box.height,height-y))},key=[r.x,r.y,r.width,r.height].join(',');if(key!==live.fit){(live.kind==='cello'||live.kind==='harp'?fitStringCamera:fitCamera)(camera,live.view.root,r,live.kind);live.fit=key;}return r;}
 return{open,close,cancel:()=>close(false),pause,camera,viewport,get active(){return !!live;},tick(dt){live?.session.update(dt);},snapshot:()=>live?{kind:live.kind,paused:live.paused,pressed:[...live.pressed],audio:live.engine?.snapshot()??audio.snapshot()}:null};
}
